parameters.jsCode:
// Turn a free-form Telegram message into the same ticket shape the
// classification logic expects. Telegram gives us raw chat text, not the
// structured {model, firmware_version, installer_type} fields a real
// installer app would send — those default to "not provided via chat" here.
// A production version would ask one follow-up question, or have the
// installer app tag the chat with equipment context (e.g. a QR scan at the
// unit) instead of relying on free text for that part.
const msg = $json.message;
const text = (msg && msg.text) || '';

// Pull out a known-style fault code if the installer happened to mention one
// (e.g. "error code E4", "CONN-01") — same codes as the lookup table.
const codeMatch = text.match(/\b(E\d{1,2}|CONN-\d{2})\b/i);
const faultCode = codeMatch ? codeMatch[1].toUpperCase() : '';

return {
  json: {
    chat_id: msg.chat.id,
    telegram_user: (msg.from && (msg.from.username || msg.from.first_name)) || 'unknown',
    model: 'not provided via chat',
    firmware_version: 'not provided via chat',
    installer_type: 'not provided via chat',
    fault_code: faultCode,
    reported_symptom: text
  }
};

// Deterministic fault-code lookup — mirrors the archetypes in
// data/synthetic_fault_dataset.csv (generate_synthetic_fault_dataset.js).
// Known structured fault codes skip the LLM entirely: fast, free, and
// auditable. Unknown/blank codes (typically connectivity or installer-error
// reports, which rarely carry a formal code) fall through to the LLM step.
const KNOWN_CODES = {
  E4: {
    category: 'hardware_fault',
    fix_or_escalation_action: 'Escalate to hardware service technician (compressor/refrigerant circuit inspection). Not resolvable by app/firmware update.'
  },
  E7: {
    category: 'hardware_fault',
    fix_or_escalation_action: 'Escalate to hardware service technician (compressor/refrigerant circuit inspection). Not resolvable by app/firmware update.'
  },
  E12: {
    category: 'hardware_fault',
    fix_or_escalation_action: 'Escalate to hardware service technician (compressor/refrigerant circuit inspection). Not resolvable by app/firmware update.'
  },
  E2: {
    category: 'installer_error',
    fix_or_escalation_action: 'Correct commissioning step per install checklist (wiring, pressure fill, sensor orientation, or valve position); no manufacturer escalation needed.'
  },
  'CONN-01': {
    category: 'connectivity_issue',
    fix_or_escalation_action: 'Re-pair the control unit via the installer app, confirm router 2.4GHz band is enabled, and check smart-meter-gateway certificate status. No hardware visit required.'
  }
};

const item = $input.item.json;
const code = String(item.fault_code || '').trim().toUpperCase();
const match = KNOWN_CODES[code];

return {
  json: {
    ...item,
    matched: !!match,
    category: match ? match.category : null,
    fix_or_escalation_action: match ? match.fix_or_escalation_action : null,
    confidence: match ? 1 : null,
    source: match ? 'lookup' : null
  }
};

// Parse the OpenAI Chat Completions response and recover the original
// ticket fields (the HTTP Request node's output replaces $json with
// OpenAI's response body, so the source ticket fields are pulled back from
// the lookup step).
const original = $('Lookup Known Fault Code').item.json;
const response = $input.item.json;

let parsed;
try {
  const text = response.choices[0].message.content;
  parsed = JSON.parse(text);
} catch (err) {
  // Fail safe: if the model output can't be parsed, escalate rather than
  // guess — never silently default to a "no action needed" outcome.
  parsed = {
    category: 'hardware_fault',
    fix_or_escalation_action: 'Could not parse model output — escalating to a senior technician as a safe default.',
    confidence: 0
  };
}

return {
  json: {
    ...original,
    category: parsed.category,
    fix_or_escalation_action: parsed.fix_or_escalation_action,
    confidence: parsed.confidence,
    source: 'llm'
  }
};

// Format the classification result as a short Telegram-friendly reply.
const item = $json;
const emoji = item.status === 'escalated' ? '\u{1F527}' : '\u2705'; // wrench vs check
const categoryLabel = {
  hardware_fault: 'Hardware fault',
  connectivity_issue: 'HEMS connectivity issue',
  installer_error: 'Installer/commissioning error'
}[item.category] || item.category;

const lines = [
  emoji + ' *' + categoryLabel + '*',
  '',
  item.message,
  '',
  '_Source: ' + (item.source === 'lookup' ? 'fault-code lookup' : 'AI classification') +
    (item.confidence != null && item.confidence !== '' ? ' (confidence ' + item.confidence + ')' : '') + '_'
];

return {
  json: {
    chat_id: item.chat_id,
    reply_text: lines.join('\n')
  }
};
